// Combine AM products (header) + inventory (per-SKU UPC/color/size) into
// canonical Item[] -- same logic as am-data-pulls.json's "Combine & Parse
// Items" node. Keep these two in sync if adapters/erp/apparelmagic/lib/parseItem.js changes.
const num = (v) => (v == null || v === '' ? null : Number(v));
const products = $('Get AM Products').first().json.response || [];
const skus = $('Get AM Inventory (SKUs)').first().json.response || [];
const skusByProduct = {};
for (const sku of skus) {
  (skusByProduct[sku.product_id] ??= []).push(sku);
}

return products.map((product) => ({ json: { item: {
  productId: product.product_id, styleNumber: product.style_number, description: product.description ?? null,
  category: product.category || null, group: product.group || null, origin: product.origin || null, content: product.content || null,
  weight: num(product.weight), boxSize: product.box_size || null, isTaxable: product.is_taxable === '1',
  cost: num(product.cost), price: num(product.price),
  skus: (skusByProduct[product.product_id] || []).map((sku) => ({
    skuId: sku.sku_id, color: sku.attr_2 || null, colorName: sku.attr_2_name || null, size: sku.size || null,
    upc: sku.upc_display || sku.upc_11 || null, price: num(sku.price), cost: num(sku.cost), weight: num(sku.weight), active: sku.active === '1',
  })),
} } }));

// Ports adapters/edi/x12-dcg/lib/{envelope,build888}.js into a single n8n
// Code node (Code nodes can't import repo files). Keep in sync with those
// two files if the builder logic changes -- see adapters/edi/x12-dcg/schema-notes.md
// for the full field mapping and every open question flagged below.
const ELEMENT_SEP = '|';
const SEGMENT_TERM = '\n';
function segment(...elements) { return elements.map((e) => (e ?? '')).join(ELEMENT_SEP); }
function pad15(value) { return String(value ?? '').padEnd(15, ' ').slice(0, 15); }

function buildEnvelope(cfg, bodySegments) {
  const {
    senderQualifier = 'ZZ', senderId, receiverQualifier = 'ZZ', receiverId,
    interchangeControlNumber, groupControlNumber, transactionSetControlNumber = '0001',
    functionalIdentifierCode, transactionSetIdentifierCode,
    responsibleAgencyCode = 'X', versionReleaseIndustryCode = '004010',
    interchangeControlVersion = '00401', usageIndicator = 'T', date = new Date(),
  } = cfg;
  const yy = String(date.getUTCFullYear()).slice(2);
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  const hh = String(date.getUTCHours()).padStart(2, '0');
  const min = String(date.getUTCMinutes()).padStart(2, '0');
  const isaDate = `${yy}${mm}${dd}`;
  const gsDate = `${date.getUTCFullYear()}${mm}${dd}`;
  const time = `${hh}${min}`;
  const isaControl = String(interchangeControlNumber).padStart(9, '0');
  const isa = segment('ISA', '00', pad15(''), '00', pad15(''), senderQualifier, pad15(senderId), receiverQualifier, pad15(receiverId), isaDate, time, 'U', interchangeControlVersion, isaControl, '0', usageIndicator, '>');
  const gs = segment('GS', functionalIdentifierCode, senderId, receiverId, gsDate, time, String(groupControlNumber), responsibleAgencyCode, versionReleaseIndustryCode);
  const st = segment('ST', transactionSetIdentifierCode, transactionSetControlNumber);
  const se = segment('SE', String(bodySegments.length + 2), transactionSetControlNumber);
  const ge = segment('GE', '1', String(groupControlNumber));
  const iea = segment('IEA', '1', isaControl);
  return [isa, gs, st, ...bodySegments, se, ge, iea].join(SEGMENT_TERM) + SEGMENT_TERM;
}

const num888 = (v) => (v == null ? '0.000' : Number(v).toFixed(3));
function vendorItemNumber(item, sku) { return `${item.styleNumber ?? ''}${sku.color ?? ''}${sku.size ?? ''}`.toUpperCase().replace(/\s+/g, ''); }
function buildN1({ vendorName, divisionCode }) {
  const elements = ['N1', 'VN', vendorName];
  if (divisionCode) elements.push('92', divisionCode);
  return segment(...elements);
}
function buildG62(date) {
  const ccyymmdd = `${date.getUTCFullYear()}${String(date.getUTCMonth() + 1).padStart(2, '0')}${String(date.getUTCDate()).padStart(2, '0')}`;
  return segment('G62', '7', ccyymmdd);
}
function buildG53(maintenanceType) { return segment('G53', maintenanceType); }
function buildG39(item, sku) {
  return segment('G39', sku.upc ?? '', 'VN', vendorItemNumber(item, sku), '', num888(sku.weight ?? item.weight), 'G', 'L', '0.000', 'IN', '0.000', 'IN', '0.000', 'IN', '1.000', 'CI', '', '1', '1', 'EA', '', '', '', 'DI', item.group || item.category || '');
}
function buildG69(item) { return segment('G69', item.description ?? ''); }
function buildN9Block(item, sku, { divisionCode }) {
  const blocks = [segment('N9', 'BO', sku.color ?? '')];
  if (divisionCode) blocks.push(segment('N9', 'DV', divisionCode));
  blocks.push(segment('N9', 'IT', item.styleNumber ?? ''));
  blocks.push(segment('N9', 'IZ', sku.size ?? ''));
  if (sku.color) blocks.push(segment('N9', 'VC', sku.color, sku.colorName ?? ''));
  return blocks;
}
function build888(items, options = {}) {
  const { vendorName, divisionCode, maintenanceType = '003', date = new Date(), envelope = {} } = options;
  const body = [buildN1({ vendorName, divisionCode }), buildG62(date), buildG53(maintenanceType)];
  for (const item of items) {
    for (const sku of item.skus ?? []) {
      body.push(buildG39(item, sku));
      body.push(buildG69(item));
      body.push(...buildN9Block(item, sku, { divisionCode }));
    }
  }
  return buildEnvelope({ functionalIdentifierCode: 'QG', transactionSetIdentifierCode: '888', ...envelope, date }, body);
}

const items = $input.all().map((i) => i.json.item);
const now = new Date();
// Timestamp-derived control number until the Supabase control-number
// sequence exists (migration 0002, not yet written -- see dcg-sftp-design.md).
const controlNumber = Number(String(Date.now()).slice(-9));

const x12 = build888(items, {
  vendorName: 'SCL FOOTWEAR', // TBD -- confirm exact expected value with Chi Cao, see schema-notes.md
  date: now,
  envelope: {
    senderId: 'SCLFOOTWEAR',  // TBD -- confirm exact ISA sender ID DCG expects for SCL
    receiverId: 'DCG',        // TBD -- confirm exact ISA receiver ID DCG expects for SCL
    interchangeControlNumber: controlNumber,
    groupControlNumber: controlNumber,
    usageIndicator: 'T', // TEST -- flip to 'P' only once DCG confirms this is a real send
  },
});

const fileName = `SCL_888_${now.toISOString().replace(/[:.]/g, '-')}.txt`;
const productIds = items.map((i) => i.productId).join(',');
const dedupeKey = `888|${now.toISOString().slice(0, 10)}|${productIds}`;

return [{
  json: {
    fileName, dedupeKey, correlationId: dedupeKey,
    itemCount: items.length, productIds,
    docType: '888', direction: 'outbound', status: 'created',
    externalIds: JSON.stringify({ controlNumber, productIds: items.map((i) => i.productId) }),
  },
  binary: {
    data: { data: Buffer.from(x12, 'utf-8').toString('base64'), mimeType: 'text/plain', fileName },
  },
}];

// Postgres nodes don't reliably pass through binary data from their input
// item, so pull the X12 file's binary back from Build 888 X12 by name, and
// merge in the correlation_id Claim & Log just produced (needed by Mark Sent).
const meta = $('Build 888 X12').item.json;
const claim = $json;
return [{
  json: { ...meta, correlationId: claim.correlation_id },
  binary: $('Build 888 X12').item.binary,
}];
